    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 81-year-old female with hypertension and type 2 diabetes is admitted for symptomatic hypoglycemia (blood glucose 20 mg/dL). A pill count reveals that the patient has been taking double doses of her glimepiride and missing her antihypertensive medications because the multiple pill bottles are confusing. Her cognitive screening shows mild executive dysfunction. Which of the following is the most effective initial intervention to improve medication adherence?', '["Simplify the medication regimen, consolidate dosing times, implement a pre-filled pill organizer (e.g., pillbox or blister packs), and enlist a family member or home health nurse to supervise medication administration", "Prescribe a second-generation antipsychotic to improve the patient''s focus on pill bottles", "Advise the patient to memorize the chemical names and colors of all her pills", "Discontinue all oral diabetes medications and transition to multiple-daily-injection insulin therapy to simplify the regimen", "Admit the patient to the hospital indefinitely for medication administration"]'::jsonb, 0, 'Medication management is a critical IADL. Impairments in this domain can lead to life-threatening errors (e.g., severe hypoglycemia or hypertensive crisis). For older adults with cognitive or executive impairment, the most effective adherence strategies are: (1) Simplifying the regimen (reducing pill burden, stopping non-essential drugs); (2) Consolidating dosing to once daily if possible; (3) Using assistive devices (pre-filled weekly pillboxes, blister packaging); and (4) Enlisting social support (family, home health nurse) to fill and monitor the system. Transitioning to complex insulin regimens would increase the risk of errors. (Ref: Hazzard''s Ch. 12, Ch. 30)'),
